<script>
(function(){
var pid="b3a1c9e4-6f2d-4a8b-9c3e-2d1f5a7b8c90";
var sel=new Set();
var jobInterval=null;

// Job progress polling
function pollJobs(){
ApiClient.ajax({type:'GET',url:ApiClient.getUrl('Plugins/PreTranscode/Jobs')})
.then(function(r){return r.json();})
.then(function(jobs){renderJobs(jobs);});
}

// U4+U5: Enhanced job rendering with summary
function renderJobs(jobs){
var panel=document.getElementById('JobPanel');
var summary=document.getElementById('JobSummary');
var empty=document.getElementById('JobEmpty');

if(!jobs||!jobs.length){
panel.style.display='none';
summary.style.display='none';
empty.style.display='';
// Also hide inline job panel in library tab
var libJobPanel=document.getElementById('LibJobPanel');
if(libJobPanel) libJobPanel.style.display='none';
return;
}
empty.style.display='none';

// U5: Calculate summary stats
var total=jobs.length;
var completed=0,running=0,queued=0,failed=0,cancelled=0;
var totalSrcMb=0,totalOutMb=0;
jobs.forEach(function(j){
switch(j.Status){
case 'Completed': completed++; break;
case 'Running': running++; break;
case 'Queued': queued++; break;
case 'Failed': failed++; break;
case 'Cancelled': cancelled++; break;
}
totalSrcMb+=j.SourceSizeMb||0;
if(j.Status==='Completed') totalOutMb+=j.OutputSizeMb||0;
});
summary.style.display='';
document.getElementById('SummaryTotal').textContent=total+' dosya';
document.getElementById('SummarySize').textContent=totalSrcMb>=1024?(totalSrcMb/1024).toFixed(1)+' GB':Math.round(totalSrcMb)+' MB';
document.getElementById('StatCompleted').innerHTML='<span class="pt-stat-icon">&#10004;</span> <span class="pt-summary-value">'+completed+'</span>';
document.getElementById('StatRunning').innerHTML='<span class="pt-stat-icon">&#9654;</span> <span class="pt-summary-value">'+running+'</span>';
document.getElementById('StatQueued').innerHTML='<span class="pt-stat-icon">&#9203;</span> <span class="pt-summary-value">'+queued+'</span>';
document.getElementById('StatFailed').innerHTML='<span class="pt-stat-icon">&#10006;</span> <span class="pt-summary-value">'+(failed+cancelled)+'</span>';
var savedMb=totalSrcMb-totalOutMb;
var savedEl=document.getElementById('StatSaved');
if(completed>0&&savedMb>0){
savedEl.style.display='';
savedEl.innerHTML='&#128190; <span class="pt-summary-value">'+(savedMb>=1024?(savedMb/1024).toFixed(1)+' GB':Math.round(savedMb)+' MB')+'</span>';
}else{
savedEl.style.display='none';
}

// U4: Render enhanced job items
panel.style.display='';
var html='<div class="pt-job-panel"><div class="pt-job-header">&#9881; İşlem Durumu</div>';
jobs.forEach(function(j){
var statusIcon,statusColor,statusText;
if(j.Status==='Running'){statusIcon='&#9654;';statusColor='#30d158';statusText='Kodlanıyor...';}
else if(j.Status==='Queued'){statusIcon='&#9203;';statusColor='#f5c542';statusText='Kuyrukta';}
else if(j.Status==='Completed'){statusIcon='&#10004;';statusColor='#30d158';statusText='Tamamlandı';}
else if(j.Status==='Cancelled'){statusIcon='&#9209;';statusColor='#f5c542';statusText=j.Error||'İptal Edildi';}
else{statusIcon='&#10006;';statusColor='#ff6b6b';statusText=j.Error||'Hata';}

var pct=Math.round(j.ProgressPercent||0);
var outMb=j.OutputSizeMb||0;
var srcMb=j.SourceSizeMb||0;
var sizeStr=outMb>0?(outMb>=1024?(outMb/1024).toFixed(2)+'GB':Math.round(outMb)+'MB'):'0MB';
var srcStr=srcMb>0?(srcMb>=1024?(srcMb/1024).toFixed(2)+'GB':Math.round(srcMb)+'MB'):'?';

// Cancel button
var cancelBtn='';
if(j.Status==='Running'){
cancelBtn='<button data-cancel-id="'+j.ItemId+'" class="pt-cancel-btn">İptal</button>';
}

// U4: Encoder badge (GPU vs CPU)
var encoderBadge='';
var isGpu=false;
if(j.EncoderType){
var enc=j.EncoderType.toLowerCase();
isGpu=!enc.startsWith('libx');
var gpuLabel=isGpu?'GPU':'CPU';
encoderBadge='<span class="pt-job-badge '+(isGpu?'gpu':'cpu')+'">'+j.EncoderType+' ('+gpuLabel+')</span>';
}

// U4: Codec conversion badge
var codecBadge='';
if(j.CodecConversion){
codecBadge='<span class="pt-job-badge">'+j.CodecConversion+'</span>';
}

// U4: Speed and ETA
var speedEta='';
if(j.Status==='Running'){
if(j.EncodeSpeedFps>0){
speedEta+='<span>'+j.EncodeSpeedFps.toFixed(1)+' MB/s</span>';
}
if(j.EtaText){
if(speedEta) speedEta+=' | ';
speedEta+='<span>ETA: '+j.EtaText+'</span>';
}
}

html+='<div class="pt-job-item">';
html+='<span class="pt-job-icon" style="color:'+statusColor+';">'+statusIcon+'</span>';
html+='<div class="pt-job-info">';
html+='<div class="pt-job-title-row">';
html+='<span class="pt-job-name">'+esc(j.Name)+'</span>';
html+='<span class="pt-job-percent">'+pct+'%</span>'+cancelBtn;
html+='</div>';
// Progress bar
html+='<div class="pt-job-progress-bg">';
var fillClass=j.Status==='Running'?'running':'';
html+='<div class="pt-job-progress-fill '+fillClass+'" style="width:'+pct+'%;background:'+(!fillClass?statusColor:'')+';"></div>';
html+='</div>';
// Badges
if(encoderBadge||codecBadge){
html+='<div class="pt-job-badges">'+codecBadge+encoderBadge+'</div>';
}
// Meta
html+='<div class="pt-job-meta">';
html+='<span>'+sizeStr+' / '+srcStr+'</span>';
if(speedEta){
html+='<span>'+speedEta+'</span>';
}else{
html+='<span>'+statusText+'</span>';
}
html+='</div>';
html+='</div></div>';
});
html+='</div>';
panel.innerHTML=html;

// Bind cancel buttons
panel.querySelectorAll('.pt-cancel-btn').forEach(function(btn){
btn.onclick=function(){
var jobId=this.getAttribute('data-cancel-id');
if(!confirm('Bu işlemi iptal etmek istediğinize emin misiniz?')) return;
ApiClient.ajax({type:'POST',url:ApiClient.getUrl('Plugins/PreTranscode/Cancel/'+jobId)});
};
});

// Keep polling if there are running/queued jobs
var hasActive=jobs.some(function(j){return j.Status==='Running'||j.Status==='Queued';});
if(!hasActive&&jobInterval){clearInterval(jobInterval);jobInterval=null;setTimeout(function(){panel.style.display='none';},5000);}

// Also show a mini status in library tab if jobs are active
var libJobPanel=document.getElementById('LibJobPanel');
if(libJobPanel&&hasActive){
var activeJobs=jobs.filter(function(j){return j.Status==='Running'||j.Status==='Queued';});
var miniHtml='<div class="pt-job-panel" style="margin-bottom:1em;"><div class="pt-job-header">&#9881; '+activeJobs.length+' işlem devam ediyor <a href="#" id="ShowJobsLink" style="color:var(--accent-color,#e50914);margin-left:0.5em;font-size:0.85em;">İşler sekmesine git</a></div></div>';
libJobPanel.innerHTML=miniHtml;
libJobPanel.style.display='';
document.getElementById('ShowJobsLink').onclick=function(e){e.preventDefault();showTab('j');};
}else if(libJobPanel){
libJobPanel.style.display='none';
}
}

// U2: Three-tab navigation
function showTab(t){
var lb=document.getElementById('TabLibrary');
var jb=document.getElementById('TabJobs');
var sb=document.getElementById('TabSettings');
var pl=document.getElementById('PanelLibrary');
var pj=document.getElementById('PanelJobs');
var ps=document.getElementById('PanelSettings');

[lb,jb,sb].forEach(function(b){b.classList.remove('active');});
[pl,pj,ps].forEach(function(p){p.style.display='none';});

if(t==='l'){
pl.style.display='';
lb.classList.add('active');
}else if(t==='j'){
pj.style.display='';
jb.classList.add('active');
pollJobs(); // refresh when opening jobs tab
}else{
ps.style.display='';
sb.classList.add('active');
loadCfg();
}
}
document.getElementById('TabLibrary').onclick=function(){showTab('l');};
document.getElementById('TabJobs').onclick=function(){showTab('j');};
document.getElementById('TabSettings').onclick=function(){showTab('s');};

function esc(s){var d=document.createElement('span');d.textContent=s;return d.innerHTML;}
function purl(id){return ApiClient.getUrl('Items/'+id+'/Images/Primary');}
function fsize(mb){return mb>=1024?(mb/1024).toFixed(1)+' GB':Math.round(mb)+' MB';"
}

